import{_ as e,a,c as t}from"./chunks/framework.BkXmWmgX.js";const f=JSON.parse('{"title":"Memoization 단계별로 구현하기 | OTW for FE","titleTemplate":false,"description":"","frontmatter":{"layout":"post","title":"OTW for FE","titleTemplate":false,"lang":"ko"},"headers":[],"params":{"id":"0269c0cd-b5f8-4f29-8457-f7976befb282","title":"Memoization 단계별로 구현하기","date":"2024-06-19","coverUrl":null,"html":"<h2 data-notion-block-id=\\"4d4acef3-eeba-4eea-ae7a-84917f84f105\\" id=\\"4d4acef3-eeba-4eea-ae7a-84917f84f105\\">Memoization 단계별로 구현하기</h2><a href=\\"https://dev.to/thekashey/weak-memoization-in-javascript-4po6\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/thekashey/weak-memoization-in-javascript-4po6</a><p data-notion-block-id=\\"8c0fa114-2b0e-4b58-bce2-5d101d853511\\"><b>심윤섭</b>: 클로저, This, 그리고 Weakmap을 소개하면서 reselect의 구현을 단계적으로 다가가는 글입니다. JS의 중요한 개념들을 친절히 설명하면서 다가가기 때문에 꼭 읽어보시면 좋습니다. 번외로 WeakMap이 예시로 들은 라이브러리 외에도 memoization을 위해 많이 쓰이고 있습니다(ex. <a href=\\"https://blog.axlight.com/posts/you-might-not-need-react-query-for-jotai/\\">Jotai</a>).</p><h2 data-notion-block-id=\\"7d25bf57-fc00-4550-af60-f285baddad43\\" id=\\"7d25bf57-fc00-4550-af60-f285baddad43\\">HTMX의 단순함</h2><a href=\\"https://www.erikheemskerk.nl/htmx-simplicity/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.erikheemskerk.nl/htmx-simplicity/</a><p data-notion-block-id=\\"25a63c5e-e23b-4a9d-afdf-e94538cc00e7\\"><b>심윤섭</b>: 저자는 은탄환은 없다라는 것을 말하면서도 간단한 UI를 만들기 위해 자바스크립트를 너무 많이 사용한다는 것을 동시에 말합니다. 그러면서 간단한 UI를 만든다면 htmx정도면 괜찮다는 주장을 펼치는 글입니다. 하지만 JS 프레임워크에 익숙해진 개발자들과 많은 인터렉션을 원하는 요구사항에 맞춰서 HTMX을 많이 쓸 수 있을지는 의문이 드네요.</p><h2 data-notion-block-id=\\"8401be1c-6d02-47b0-90d6-4ae08ac46459\\" id=\\"8401be1c-6d02-47b0-90d6-4ae08ac46459\\">Valibot 0.31 출시</h2><a href=\\"https://valibot.dev/blog/valibot-v0.31.0-is-finally-available/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://valibot.dev/blog/valibot-v0.31.0-is-finally-available/</a><p data-notion-block-id=\\"d2410ca1-a084-46c1-99b3-e078b00ad0e3\\"><b>심윤섭</b>: zod가 출시되면서 schema 검증 도구로서 많은 사람들에게 이용되었습니다. Valibot은 zod와 비슷한 구조를 이어가면서 Tree shaking, 작은 번들사이즈를 목표로 만들어졌습니다. Valibot은 적은 번들사이즈로 많은 유연성을 목표로 계속 개발하고 있으므로 계속 지켜볼만하다고 생각합니다. 번외로 여러 Schema 검증 도구를 비슷한 인터페이스로 사용할 수 있는 노력이 담겨있는 <a href=\\"https://github.com/decs/typeschema\\"><code>typeschema</code></a>나 <a href=\\"https://github.com/standard-schema/standard-schema\\"><code>standard-schema</code></a>도 계속 살펴보면 좋다고 생각합니다.</p><h2 data-notion-block-id=\\"011c26fc-e180-4b41-b912-007040d7fa76\\" id=\\"011c26fc-e180-4b41-b912-007040d7fa76\\">협업 기능 구현을 위한 아키텍쳐</h2><a href=\\"https://mattweidner.com/2024/06/04/server-architectures.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://mattweidner.com/2024/06/04/server-architectures.html</a><p data-notion-block-id=\\"b146833e-28a1-4489-827a-80a7a91618c3\\"><b>심윤섭</b>: 협업 기능을 구현하기 위해(ex. Google Docs, Notion…) 서버에서 다른 변경사항이 들어왔을 경우 처리하는 방식을 구현한 라이브러리를 많이 사용합니다. 이 글에서는 협업 기능을 구현한 라이브러리들이 어떻게 동작하는지 상세하게 설명합니다. 마지막으로 분산 협업 서버도 소개하고 있어 기존 중앙 서버 처리 방식의 알고리즘과 향후 나아갈 방향을 알기 위해 가볍게 볼만하다고 생각합니다.</p><h2 data-notion-block-id=\\"110a330e-5d04-4c3f-8450-05b7a8c43375\\" id=\\"110a330e-5d04-4c3f-8450-05b7a8c43375\\">출시 주간</h2><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-rc/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-rc/</a><a href=\\"https://astro.build/blog/astro-4100/#rewrite-for-all-http-methods\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://astro.build/blog/astro-4100/#rewrite-for-all-http-methods</a><a href=\\"https://deno.com/blog/v1.44\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://deno.com/blog/v1.44</a><p data-notion-block-id=\\"34f7ddde-44f8-478e-93b7-16621aad7c3f\\">TypeScript 5.5에서의 추론 강화, 정규표현식 검사, 선언 파일 지원 강화, 제안단계의 Set 메소드 지원..을 출시할 것이라고 예고하였고, Astro의 환경 변수 검사, 미들웨어 재작성… 기능과 함께 4.10이 출시되었습니다. Deno는 비공개 npm 저장소, Node.js 호환성 지원과 성능 향상을 가진 1.44를 출시했네요.</p><h2 data-notion-block-id=\\"6e947f37-d04f-41c5-8898-9f0ab795f62d\\" id=\\"6e947f37-d04f-41c5-8898-9f0ab795f62d\\">NodeJS에서 setTimeout 메모리 누수</h2><a href=\\"https://lucumr.pocoo.org/2024/6/5/node-timeout/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://lucumr.pocoo.org/2024/6/5/node-timeout/</a><p data-notion-block-id=\\"e7ec45dc-c061-4d11-b03b-fb9e15f9e176\\">NodeJS에서 <code>setTimeout</code>이 브라우저와 다르게 객체를 반환하는데, 객체에 closure에 관한 것을 저장하기 때문에 메모리 누수가 있을 수 있다는 글입니다.</p><h2 data-notion-block-id=\\"f76c771b-c8fa-434e-aede-2a315473dc3f\\" id=\\"f76c771b-c8fa-434e-aede-2a315473dc3f\\">파라미터가 여러개일 경우 함수를 합성하는 방법</h2><a href=\\"https://jrsinclair.com/articles/2024/how-to-compose-functions-that-take-multiple-parameters-epic-guide/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://jrsinclair.com/articles/2024/how-to-compose-functions-that-take-multiple-parameters-epic-guide/</a><p data-notion-block-id=\\"fdd96522-0b2b-4130-90b9-0e8a63559544\\">함수형 프로그래밍 개념에 합성이라는 개념을 사용하려면 매개변수가 일정해야하는데, 이를 복합적 데이터구조나 커링을 통해 해결하는 방법을 보여줍니다.</p><h2 data-notion-block-id=\\"5db98a0c-a3e3-4653-af36-2e962a76c5b7\\" id=\\"5db98a0c-a3e3-4653-af36-2e962a76c5b7\\">FlatList 성능 최적화하기</h2><a href=\\"https://www.andydevs.dev/articles/flatlist-rendering-techniques\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.andydevs.dev/articles/flatlist-rendering-techniques</a><p data-notion-block-id=\\"5c5e8496-35cb-44b7-afac-11301ac22ce1\\">React Native에서는 보통 리스트를 보여주기 위해 <a href=\\"https://github.com/Shopify/flash-list\\">FlashList</a>를 사용하는데, 사용하지 않을 경우 FlatList를 성능 최적화하는 방법을 설명하는 글입니다.</p><h2 data-notion-block-id=\\"654234f1-9bdb-486e-a33c-89b20cb2a7bc\\" id=\\"654234f1-9bdb-486e-a33c-89b20cb2a7bc\\">Vector DB란 무엇인가요?</h2><a href=\\"https://learn.microsoft.com/en-us/semantic-kernel/memories/vector-db\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://learn.microsoft.com/en-us/semantic-kernel/memories/vector-db</a><p data-notion-block-id=\\"4c360e40-6358-4dd8-9eef-c2e35205982c\\">많은 DB 서비스형 회사에서 Vector DB를 소개하는 김에, Vector DB를 소개하는 글을 가져왔습니다.</p>"},"relativePath":"news/post/0269c0cd-b5f8-4f29-8457-f7976befb282.md","filePath":"news/post/[id].md"}'),o={name:"news/post/0269c0cd-b5f8-4f29-8457-f7976befb282.md"};function r(c,i,d,s,l,n){return a(),t("div")}const h=e(o,[["render",r]]);export{f as __pageData,h as default};
